local a="create_radar:network_filterer_block_entity_0"local b="minecraft:chest_0"local function c(d)if textutils and textutils.serialize then local e,f=pcall(textutils.serialize,d)if e then return f end end;return tostring(d)end;local function g(h)local i=peripheral.wrap(h)if not i then return{name=h,error="Peripheral not found"}end;if type(i.list)~="function"or type(i.size)~="function"then return{name=h,error="Peripheral is not an inventory"}end;local j=i.list()local k={}for l=1,i.size()do local m=j[l]if m then local n=i.getItemDetail and i.getItemDetail(l)or m;k[#k+1]={slot=l,stack=m,detail=n}end end;return{name=h,size=i.size(),slots=k}end;local o={title="Read-only filter inventory report",inventories={g(a),g(b)}}local p=c(o)print(p)local q=shell.getRunningProgram()local r=fs.combine(fs.getDir(q),"filter_inventory_report.txt")local s=fs.open(r,"w")if not s then error("Could not write "..r)end;s.write(p)s.close()print("\nSaved to "..r)
